<template><main class="login-page"><section class="login-panel"><div class="login-brand"><span>A</span><p>ANALYTICS<span>OS</span></p></div><div class="login-copy"><p class="overline">WELCOME BACK</p><h1>データプラットフォームにログイン</h1><p>ビジネスデータをつなぎ、成長のシグナルを継続的に把握します。</p></div><el-form ref="formRef" :model="form" :rules="rules" class="login-form" size="large" @submit.prevent="submit"><el-form-item prop="email" label="メールアドレス"><el-input v-model="form.email" placeholder="admin@example.com" autocomplete="email" /></el-form-item><el-form-item prop="password" label="パスワード"><el-input v-model="form.password" type="password" placeholder="パスワードを入力" show-password autocomplete="current-password" @keyup.enter="submit" /></el-form-item><el-button class="login-button" type="primary" :loading="auth.isLoading" native-type="submit">{{ auth.isLoading ? '認証中…' : 'コンソールにログイン' }}</el-button></el-form><p class="login-hint">デモアカウント：admin@example.com · Admin123!</p></section><section class="visual-panel"><div class="visual-orb" /><div class="visual-copy"><p class="overline">E-COMMERCE INTELLIGENCE</p><h2>経営判断を<br><em>さらに速く。</em></h2><p>売上、顧客、商品、リアルタイム運用データを一元化します。</p></div><div class="visual-stats"><span><strong>180</strong>日分の業務データ</span><span><strong>5,000</strong>件のサンプル注文</span></div></section></main></template>

<script setup lang="ts">
import { reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ElMessage, type FormInstance, type FormRules } from 'element-plus';
import { useAuthStore } from '../stores/auth';
const auth = useAuthStore(); const router = useRouter(); const route = useRoute(); const formRef = ref<FormInstance>(); const form = reactive({ email: 'admin@example.com', password: 'Admin123!' });
const rules: FormRules<typeof form> = { email: [{ required: true, message: 'メールアドレスを入力してください', trigger: 'blur' }, { type: 'email', message: '有効なメールアドレスを入力してください', trigger: 'blur' }], password: [{ required: true, message: 'パスワードを入力してください', trigger: 'blur' }] };
async function submit(): Promise<void> { const valid = await formRef.value?.validate().catch(() => false); if (!valid) return; try { await auth.login(form); ElMessage.success('ログインしました。おかえりなさい'); const redirect = typeof route.query.redirect === 'string' ? route.query.redirect : '/'; await router.replace(redirect); } catch { /* global interceptor reports API errors */ } }
</script>

