-size: 48px 48px; }.visual-orb { position: absolute; top: 21%; right: 9%; width: min(27vw, 340px); aspect-ratio: 1; border: 1px solid rgba(94, 215, 255, .32); border-radius: 50%; box-shadow: 0 0 0 45px rgba(51, 164, 239, .04), 0 0 0 95px rgba(62, 116, 255, .03), 0 0 80px rgba(38, 170, 250, .24); }.visual-copy, .visual-stats { position: relative; }.visual-copy h2 { margin: 16px 0; color: #f0f8ff; font-size: clamp(38px, 4.5vw, 64px); line-height: 1.08; letter-spacing: -.06em; }.visual-copy h2 em { color: #64d9ff; font-style: normal; }.visual-copy > p:last-child { max-width: 330px; color: #98b6ce; font-size: 15px; line-height: 1.8; }.visual-stats { display: flex; gap: 40px; margin-top: 70px; color: #87a8c4; font-size: 12px; }.visual-stats strong { display: block; margin-bottom: 6px; color: #eaf7ff; font-size: 21px; }
